def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the large zero region that forms the answer panel.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = y + dy, x + dx
                        if (0 <= ny < h and 0 <= nx < w and
                                grid[ny][nx] == 0 and (ny, nx) not in seen):
                            seen.add((ny, nx))
                            stack.append((ny, nx))
            components.append(cells)

    panel = max(components, key=len)
    r0 = min(r for r, c in panel)
    r1 = max(r for r, c in panel)
    c0 = min(c for r, c in panel)
    c1 = max(c for r, c in panel)
    out = [[0] * (c1 - c0 + 1) for _ in range(r1 - r0 + 1)]

    # Count each color's separate objects outside the panel.
    counts = {}
    for color in set(v for row in grid for v in row if v != 0):
        seen_color = set()
        count = 0
        for r in range(h):
            for c in range(w):
                if (r0 <= r <= r1 and c0 <= c <= c1) or grid[r][c] != color or (r, c) in seen_color:
                    continue
                count += 1
                stack = [(r, c)]
                seen_color.add((r, c))
                while stack:
                    y, x = stack.pop()
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            ny, nx = y + dy, x + dx
                            if (0 <= ny < h and 0 <= nx < w and
                                    not (r0 <= ny <= r1 and c0 <= nx <= c1) and
                                    grid[ny][nx] == color and (ny, nx) not in seen_color):
                                seen_color.add((ny, nx))
                                stack.append((ny, nx))
        counts[color] = count

    # Each colored marker in the panel starts a row of repeated markers.
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            color = grid[r][c]
            if color != 0:
                for k in range(counts.get(color, 0)):
                    x = c - c0 + 2 * k
                    if x < len(out[0]):
                        out[r - r0][x] = color
    return out
